inline const MetadataReplacement* normalizationMetadataReplacement(const juce::String& hash)
{
    for(const auto& update:normalizationMetadataUpdates)if(hash.equalsIgnoreCase(update.oldHash))return &update;
    return nullptr;
}
template<class Identity> inline bool migrateNormalizationMetadata(Identity& identity)
{
    if(const auto* update=normalizationMetadataReplacement(identity.sha256))
    {identity={update->filename,update->sha256,update->bytes};return true;}
    return false;
}
